import numpy as np
from scipy.optimize import linear_sum_assignment
# State: tracks=[], next_id=1, preserved for the input stream.
def iou(a,b):
    ax1,ay1,ax2,ay2=a; bx1,by1,bx2,by2=b
    inter=max(0,min(ax2,bx2)-max(ax1,bx1))*max(0,min(ay2,by2)-max(ay1,by1))
    aa=max(0,ax2-ax1)*max(0,ay2-ay1); ab=max(0,bx2-bx1)*max(0,by2-by1)
    return inter/(aa+ab-inter) if aa+ab-inter>0 else 0.0
def center(box):
    x1,y1,x2,y2=box
    return (int((x1+x2)/2),int((y1+y2)/2))
if tracks and detections:
    cost=np.array([[1-iou(t['box'],d['box']) for d in detections] for t in tracks])
    rows,cols=linear_sum_assignment(cost)
else:
    cost=np.empty((len(tracks),len(detections)))
    rows,cols=[],[]
matched_tracks=set(); matched_dets=set()
for r,c in zip(rows,cols):
    if 1-cost[r,c]>=parameters['iou_threshold']:
        t=tracks[r]; d=detections[c]
        t['box']=d['box']; t['score']=d['score']; t['hits']+=1; t['misses']=0
        t['trail']=(t['trail']+[center(t['box'])])[-30:]
        matched_tracks.add(r); matched_dets.add(c)
for i,t in enumerate(tracks):
    if i not in matched_tracks: t['misses']+=1
for j,d in enumerate(detections):
    if j not in matched_dets:
        tracks.append({'id':next_id,'box':d['box'],'score':d['score'],'misses':0,'hits':1,'trail':[center(d['box'])]})
        next_id+=1
tracks=[t for t in tracks if t['misses']<=parameters['max_age']]
return [dict(t) for t in tracks]

# State per track: entry_time and alerted; retain cumulative zone
# observation time separately if an ID leaves and later returns.
now=zone['timestamp_s']; events=[]; timers={}
for crossing in zone['events']:
    tid=crossing['track_id']
    if crossing['event_type']=='restricted_zone_entry':
        entry_time[tid]=now; alerted[tid]=False
    elif crossing['event_type']=='normal_exit':
        entry_time.pop(tid,None); alerted[tid]=False
for obs in zone['observations']:
    tid=obs['track_id']
    if not obs['inside']: continue
    if tid not in entry_time: entry_time[tid]=now; alerted[tid]=False
    elapsed=max(0.0,now-entry_time[tid]); timers[tid]=elapsed
    if elapsed>=parameters['duration_seconds'] and not alerted[tid]:
        events.append({'timestamp_s':now,'frame_index':zone['frame_index'],'track_id':tid,'event_type':'prolonged_presence','confidence':obs['score'],'dwell_seconds':elapsed,'box':obs['box']})
        alerted[tid]=True
return {'timers_s':timers,'events':events}

from collections import deque
# State entry_times maps persistent track IDs to deques.
events=[]
for crossing in zone['events']:
    if crossing['event_type']!='restricted_zone_entry': continue
    tid=crossing['track_id']; now=crossing['timestamp_s']
    times=entry_times.setdefault(tid,deque())
    while times and now-times[0]>parameters['window_seconds']: times.popleft()
    times.append(now)
    if len(times)>=parameters['entry_count']:
        events.append({'timestamp_s':now,'frame_index':crossing['frame_index'],'track_id':tid,'event_type':'repeat_entry','confidence':crossing['confidence'],'entry_count_in_window':len(times),'box':crossing['box']})
return {'events':events}

